CREATE TABLE IF NOT EXISTS quakes(id TEXT PRIMARY KEY,place TEXT NOT NULL,magnitude DOUBLE PRECISION NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,payload JSONB NOT NULL); CREATE TABLE IF NOT EXISTS weather_snapshots(id BIGSERIAL PRIMARY KEY,location TEXT NOT NULL,observed_at TIMESTAMPTZ NOT NULL,payload JSONB NOT NULL); CREATE TABLE IF NOT EXISTS iss_positions(id BIGSERIAL PRIMARY KEY,observed_at TIMESTAMPTZ NOT NULL,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,payload JSONB NOT NULL); CREATE TABLE IF NOT EXISTS kp_index(id BIGSERIAL PRIMARY KEY,observed_at TIMESTAMPTZ NOT NULL,kp DOUBLE PRECISION NOT NULL,payload JSONB NOT NULL); CREATE TABLE IF NOT EXISTS eonet_events(id TEXT PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL,observed_at TIMESTAMPTZ,payload JSONB NOT NULL); CREATE TABLE IF NOT EXISTS alerts(id BIGSERIAL PRIMARY KEY,kind TEXT NOT NULL,severity TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),payload JSONB NOT NULL,delivered BOOLEAN NOT NULL DEFAULT FALSE); CREATE TABLE IF NOT EXISTS feed_health(source TEXT PRIMARY KEY,checked_at TIMESTAMPTZ NOT NULL,ok BOOLEAN NOT NULL,latency_ms BIGINT,error TEXT); CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),settings JSONB NOT NULL DEFAULT '{}'::jsonb);